// Matching Legion26972 stores and actual linked pet-battle dispatcher.
// Teams live only in memory; no character/login/save or world server process.
#include <unordered_set>
#include <array>
#include "Common.h"
#include "SharedDefines.h"
#include "UnitDefines.h"
#include "DB2Stores.h"
#include "DB2LoadInfo.h"
#include "Config.h"
#include "DatabaseEnv.h"
#include "MySQLThreading.h"
#include "ObjectGuid.h"
#include "Position.h"
#include "Timer.h"
#include "PetBattle.h"
#include "PetBattleAbilityEffect.h"
#include "GameTables.h"
#include <cstdlib>
#include <iostream>
#include <stdexcept>
static_assert(sizeof(PetBattleAbilityEffect)==0x50,"Bend Time owner context must reuse existing execution padding");
static void Require(bool value,char const*message){if(!value)throw std::runtime_error(message);}
template<class T>static void Load(T&store,char const*path){Require(store.Load(path,0),"Matching native DB2 missing");store.LoadFromDB();}
static void Fill(PetBattle&b){
 b.BattleType=PETBATTLE_TYPE_PVE;b.PveBattleType=PVE_PETBATTLE_TRAINER;b.BattleStatus=PETBATTLE_STATUS_RUNNING;b.Turn=1;b.RoundTurn=0;b.RoundFirstTeamCasting=0;
 for(uint32 t=0;t<2;++t){b.Teams[t]->ActivePetID=t*3;b.Teams[t]->TeamPetCount=3;
  for(uint32 s=0;s<3;++s){auto p=std::make_shared<BattlePetInstance>();p->ID=t*3+s;p->TeamID=t;p->PetBattleInstance=&b;p->Health=100;p->InfoMaxHealth=100;p->Level=1;p->Species=0;b.Pets[p->ID]=p;b.Teams[t]->TeamPets[s]=p;}}
}
static PetBattleAbilityEffect Hit(PetBattle&b,PetBattleAbilityTurn&turn,uint32 caster,uint32 target){PetBattleAbilityEffect e{};e.PetBattleInstance=&b;e.AbilityTurn=&turn;e.EffectInfo=sBattlePetAbilityEffectStore.LookupEntry(3482);Require(e.EffectInfo&&e.EffectInfo->BattlePetEffectPropertiesID==24,"Native damage row changed");e.Caster=caster;e.Target=target;e.AbilityID=1927;e.IsTriggered=true;return e;}
static PetBattleAura* Aura(PetBattle&b,uint32 target,uint32 ability){for(auto a:b.PetAuras)if(!a->Expired&&a->TargetPetID==target&&a->AbilityID==ability)return a;return nullptr;}
static void TriggerReceipt(PetBattle const&b,uint32 target){uint32 count=0;for(auto const&e:b.RoundEvents)if(e.EventType==PETBATTLE_EVENT_TRIGGER_ABILITY&&e.SourcePetID==int32(target)&&e.AbilityEffectID==3482)++count;Require(count==1,"Racial resurrection must emit one native trigger event from its actual recipient");}
static void Racial(PetBattle&b,uint32 target,uint32 family){for(auto s:sBattlePetSpeciesStore)if(s->PetTypeEnum==family){b.Pets[target]->Species=s->ID;Require(b.Cast(target,291,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL)==PETBATTLE_CAST_OK,"Native initialization failed");return;}throw std::runtime_error("Matching native species missing");}
static void SameFamily(PetBattle& b,uint32 ability) {
 auto data=sBattlePetAbilityStore.LookupEntry(ability);Require(data,"Matching sacrifice ability missing");
 for(auto s:sBattlePetSpeciesStore)if(s->PetTypeEnum==data->PetTypeEnum){for(auto pet:b.Pets)if(pet)pet->Species=s->ID;return;}
 throw std::runtime_error("Matching same-family neutral species missing");
}
static void Prepare(PetBattle& b,uint32 ability,uint32 caster,bool mechanical=false) {
 Fill(b);SameFamily(b,ability);if(mechanical)Racial(b,caster,BATTLEPET_PETTYPE_MECHANICAL);
 for(auto pet:b.Pets)if(pet){pet->Health=pet->GetMaxHealth();pet->States[BATTLEPET_STATE_Stat_CritChance]=0;pet->States[BATTLEPET_STATE_Stat_Power]=0;}
}
static void CastSacrifice(PetBattle& b,uint32 caster,uint32 ability) {
 Require(b.Cast(caster,ability,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL)==PETBATTLE_CAST_OK,"Actual authored sacrifice Cast failed");
}
static void Setup(PetBattle&b){Fill(b);for(auto p:b.Pets)for(uint32 slot=0;slot<3;++slot){p->Abilities[slot]=slot==0?110:slot==1?282:321;p->Cooldowns[slot]=7-int32(slot)*2;p->Lockdowns[slot]=0;}}
static std::array<int32,3> CDs(PetBattle&b,uint32 id){return{{b.Pets[id]->Cooldowns[0],b.Pets[id]->Cooldowns[1],b.Pets[id]->Cooldowns[2]}};}
static PetBattleAura* Bend(PetBattle&b,uint32 caster){b.Pets[caster]->Abilities[0]=1905;b.Pets[caster]->Cooldowns[0]=-1;Require(b.Cast(caster,1905,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_NONE)==PETBATTLE_CAST_OK,"Native Bend Time root Cast failed");auto a=Aura(b,caster,1904);Require(a&&a->Duration==2,"Native Bend Time must apply its authored aura without an accuracy bonus");return a;}
static uint32 CancelCount(PetBattle&b,uint32 owner){uint32 count=0;for(auto const&e:b.RoundEvents)if(e.EventType==PETBATTLE_EVENT_BUFF_CANCEL)for(auto const&u:e.Updates)if(u.Buff.AbilityID==1904&&u.TargetPetID==owner)++count;return count;}
static void ResetToOne(PetBattle&b,uint32 pet){Require(CDs(b,pet)==std::array<int32,3>{{1,1,1}},"Bend Time must reset only the actual incoming pet to its three authored cooldown values");}
static void TypeSetup(PetBattle&b){Setup(b);for(auto s:sBattlePetSpeciesStore)if(s->PetTypeEnum==BATTLEPET_PETTYPE_HUMANOID){for(auto p:b.Pets)p->Species=s->ID;break;}for(auto p:b.Pets){p->States[BATTLEPET_STATE_Stat_CritChance]=0;p->States[BATTLEPET_STATE_Stat_Power]=0;}}
static uint32 Holder(uint32 root,uint32 source){return root==574?source:(source?0:3);}
static uint32 Parent(uint32 root){return root==574?820:1418;}
static uint32 Mark(uint32 root){return root==574?1417:968;}
static int32 Type(uint32 root){return root==574?7:4;}
static void TypeRoot(PetBattle&b,uint32 root,uint32 source){Require(b.Cast(source,root,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL)==PETBATTLE_CAST_OK,"Actual Ward/Rot root failed");}
static void TypeEnd(PetBattle&b){for(auto t:b.Teams){t->Ready=true;t->ActiveAbilityId=0;t->activeAbilityTurn=t->activeAbilityTurnMax=1;}b.ProceedRound();}
static PetBattleAbilityEffect Bite(PetBattle&b,PetBattleAbilityTurn&turn,uint32 source,uint32 target){PetBattleAbilityEffect e{};e.PetBattleInstance=&b;e.AbilityTurn=&turn;e.Caster=source;e.Target=target;e.AbilityID=110;for(auto t:sBattlePetAbilityTurnStore)if(t->BattlePetAbilityID==110&&t->OrderIndex==1)for(auto x:sBattlePetAbilityEffectStore)if(x->BattlePetAbilityTurnID==t->ID&&x->BattlePetEffectPropertiesID==24){e.EffectInfo=x;return e;}throw std::runtime_error("Native Bite damage row missing");}
static void TypeKill(PetBattle&b,uint32 victim){PetBattleAbilityTurn turn{};auto hit=Hit(b,turn,victim?0:3,victim);hit.Damage(victim,1000);}
static uint32 OrdinarySpecies(){for(auto s:sBattlePetSpeciesStore)if(s->PetTypeEnum==BATTLEPET_PETTYPE_HUMANOID){bool passive=false;for(auto st:sBattlePetSpeciesStateStore)if(st->SpeciesID==s->ID&&st->BattlePetStateID==183)passive=true;if(!passive)return s->ID;}throw std::runtime_error("Native ordinary species missing");}
static void RoboSetup(PetBattle&b,uint32 source,uint32 overrideSpecies=1504){b.BattleType=PETBATTLE_TYPE_PVE;b.PveBattleType=PVE_PETBATTLE_TRAINER;uint32 ordinary=OrdinarySpecies();for(uint32 team=0;team<2;++team)for(uint32 slot=0;slot<3;++slot){uint32 id=team*3+slot;auto p=std::make_shared<BattlePetInstance>();p->Slot=slot;p->Species=id==source?overrideSpecies:ordinary;p->Level=25;p->Quality=3;p->Breed=3;p->Health=100000;p->Abilities[0]=id==source?1079:110;p->Abilities[1]=id==source?455:282;p->Abilities[2]=id==source?1025:321;b.AddPet(team,p);Require(b.Pets[id]!=nullptr,"Native AddPet rejected the configured valid slot");}b.Begin();}
static uint32 RoboMarks(PetBattle const&b,uint32 team){uint32 count=0;for(auto a:b.PetAuras)if(!a->Expired&&a->AbilityID==1419&&b.Pets[a->TargetPetID]&&b.Pets[a->TargetPetID]->TeamID==team)++count;return count;}
static void ClearRoboMarks(PetBattle&b,uint32 team){std::vector<PetBattleAura*> list;for(auto a:b.PetAuras)if(!a->Expired&&a->AbilityID==1419&&b.Pets[a->TargetPetID]&&b.Pets[a->TargetPetID]->TeamID==team)list.push_back(a);for(auto a:list)a->Expire(&b);}
static void CheckRobo(PetBattle&b,uint32 source,uint32 trigger,uint32 expected=3){uint32 team=b.Pets[source]->TeamID;Require(RoboMarks(b,team)==expected&&RoboMarks(b,!team)==0,"Native Roboflauge must mark exactly the actual living own roster, without leaking to its opponent");for(auto a:b.PetAuras)if(!a->Expired){Require(a->AbilityID!=1389,"An inherent Roboflauge passive must not fabricate an infinite controller aura");if(a->AbilityID==1419)Require(a->CasterPetID==source&&a->TriggerId==trigger&&a->MaxDuration==1&&b.Pets[a->TargetPetID]->States[124]==5,"Native Roboflauge marks must preserve original source, actual proc receipt and finite category");}}
static void RoboDamage(PetBattle&b,uint32 source){PetBattleAbilityTurn turn{};auto e=Hit(b,turn,source?0:3,source);e.Damage(source,b.Pets[source]->GetMaxHealth()*10);}
static uint32 PoundCases=0;
static uint32 EnemyBase(uint32 source){return source<3?3:0;}
static std::array<int32,3> EnemyHP(PetBattle const&b,uint32 source){auto base=EnemyBase(source);return{{b.Pets[base]?b.Pets[base]->Health:0,b.Pets[base+1]?b.Pets[base+1]->Health:0,b.Pets[base+2]?b.Pets[base+2]->Health:0}};}
static void PoundSetup(PetBattle&b,uint32 source,uint32 active,uint32 species=1811){RoboSetup(b,source,species);auto base=EnemyBase(source);b.SwapPet(base/3,base+active);Require(b.Teams[base/3]->ActivePetID==int32(base+active),"Actual native opponent front swap failed");for(auto p:b.Pets){p->States[BATTLEPET_STATE_Stat_Power]=0;p->States[BATTLEPET_STATE_Stat_CritChance]=0;}b.Pets[source]->Abilities[0]=1587;b.Pets[source]->Cooldowns[0]=-1;}
static void PoundRoot(PetBattle&b,uint32 source){Require(b.Cast(source,1587,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_NONE)==PETBATTLE_CAST_OK,"Actual native owned Pound root failed");}
static void SplitDamage(PetBattle const&b,uint32 source,uint32 active,std::array<int32,3> const&before){auto hp=EnemyHP(b,source);for(uint32 slot=0;slot<3;++slot)Require(before[slot]-hp[slot]==(slot==active?20:10),"Actual native Pound must hit the chosen active opponent once for20 and each fixed backline once for10");}
static void Cases(std::string const&choice){Require(choice.empty()||choice=="split"||choice=="events"||choice=="lethal"||choice=="allkill"||choice=="mechanical"||choice=="dead"||choice=="missing"||choice=="frontmissing"||choice=="miss"||choice=="frontmiss"||choice=="block"||choice=="immune"||choice=="round"||choice=="lethalround"||choice=="recast"||choice=="bounds"||choice=="missingsource"||choice=="deadsource"||choice=="wrongteam"||choice=="invalidteam"||choice=="other"||choice=="owner"||choice=="reflection"||choice=="reflectionmech","Unknown native Pound group");auto run=[&](char const*s){return choice.empty()||choice==s;};
 if(run("split"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);auto hp=EnemyHP(b,source);auto own=b.Pets[source]->Health;PoundRoot(b,source);SplitDamage(b,source,active,hp);Require(b.Pets[source]->Health==own&&b.PetXDied.empty()&&b.Pets[source]->Cooldowns[0]==0,"Ordinary native Pound cannot damage its own caster, invent a death or change its authored cooldown");++PoundCases;}
 if(run("events"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);PoundRoot(b,source);uint32 base=EnemyBase(source),other[2],next=0;for(uint32 slot=0;slot<3;++slot)if(slot!=active)other[next++]=base+slot;for(auto pair:std::array<std::pair<uint32,uint32>,3>{{{3030,base+active},{3032,other[0]},{3033,other[1]}}}){uint32 count=0;for(auto const&e:b.RoundEvents)if(e.EventType==PETBATTLE_EVENT_SET_HEALTH&&e.AbilityEffectID==pair.first)for(auto const&u:e.Updates){Require(u.TargetPetID==int32(pair.second),"Native Pound effect receipt was redirected to another actor");++count;}Require(count==1,"Each native Pound damage row must emit one real recipient health event");}++PoundCases;}
 if(run("lethal"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source);b.Pets[base+active]->Health=1;auto hp=EnemyHP(b,source);PoundRoot(b,source);for(uint32 slot=0;slot<3;++slot)if(slot!=active)Require(hp[slot]-b.Pets[base+slot]->Health==10,"A real native killing first Pound hit must not discard either surviving backline damage row");Require(!b.Pets[base+active]->IsAlive()&&b.PetXDied.size()==1&&b.PetXDied[0]==base+active&&b.Pets[source]->IsAlive(),"Lethal native Pound must retain exactly its actual enemy death");++PoundCases;}
 if(run("allkill"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source);for(uint32 slot=0;slot<3;++slot)b.Pets[base+slot]->Health=1;PoundRoot(b,source);std::unordered_set<uint32> deaths(b.PetXDied.begin(),b.PetXDied.end());Require(b.PetXDied.size()==3&&deaths.size()==3&&deaths.count(base)&&deaths.count(base+1)&&deaths.count(base+2)&&b.Pets[source]->IsAlive(),"Native Pound must finish three distinct lethal enemy rows without repeating or killing the user");++PoundCases;}
 if(run("mechanical"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source),target=base+active;Racial(b,target,BATTLEPET_PETTYPE_MECHANICAL);b.Pets[target]->Health=1;auto hp=EnemyHP(b,source);PoundRoot(b,source);for(uint32 slot=0;slot<3;++slot)if(slot!=active)Require(hp[slot]-b.Pets[base+slot]->Health==10,"Real Mechanical front revival cannot redirect native Pound backline rows");Require(b.Pets[target]->IsAlive()&&!b.Pets[target]->States[BATTLEPET_STATE_Passive_Mechanical]&&b.PetXDied.empty(),"Native Pound must preserve the first actual Mechanical revival");b.Pets[target]->Health=1;PoundRoot(b,source);Require(!b.Pets[target]->IsAlive()&&b.PetXDied.size()==1&&b.PetXDied[0]==target,"Native Pound cannot repeat the consumed Mechanical revival");++PoundCases;}
 if(run("dead"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source),dead=(active+1)%3;PetBattleAbilityTurn turn{};auto e=Hit(b,turn,source,base+dead);e.Damage(base+dead,b.Pets[base+dead]->GetMaxHealth()*10);TypeEnd(b);Require(!b.Pets[base+dead]->IsAlive()&&b.RoundResult==PETBATTLE_ROUND_RESULT_NONE,"Real prior reserve death/round cleanup failed");auto hp=EnemyHP(b,source);PoundRoot(b,source);for(uint32 slot=0;slot<3;++slot)Require(hp[slot]-b.Pets[base+slot]->Health==(slot==dead?0:slot==active?20:10),"A dead fixed backline must not redirect its Pound row to the active or other reserve");++PoundCases;}
 if(run("missing")||run("frontmissing"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active)for(bool front:{false,true})if(run(front?"frontmissing":"missing")){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source),missing=front?active:(active+1)%3;auto hp=EnemyHP(b,source);auto saved=b.Pets[base+missing];b.Pets[base+missing].reset();b.Teams[base/3]->TeamPets[missing].reset();PoundRoot(b,source);for(uint32 slot=0;slot<3;++slot)if(slot!=missing){auto expected=slot==active?20:10;auto actual=hp[slot]-b.Pets[base+slot]->Health;if(actual!=expected)std::cerr<<"Missing recipient context source="<<source<<" active="<<active<<" missing="<<missing<<" slot="<<slot<<" expected="<<expected<<" actual="<<actual<<"\n";Require(actual==expected,"A missing native root recipient cannot shift another fixed Pound damage row");}b.Pets[base+missing]=saved;b.Teams[base/3]->TeamPets[missing]=saved;++PoundCases;}
 if(run("miss"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);b.Pets[source]->States[BATTLEPET_STATE_Stat_Accuracy]=-100;auto hp=EnemyHP(b,source);PoundRoot(b,source);Require(hp==EnemyHP(b,source)&&b.PetXDied.empty(),"Native Pound accuracy failure must preserve all intended actors");++PoundCases;}
 if(run("frontmiss"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source);b.Pets[base+active]->States[BATTLEPET_STATE_Stat_Dodge]=100;auto hp=EnemyHP(b,source);PoundRoot(b,source);for(uint32 slot=0;slot<3;++slot)Require(hp[slot]-b.Pets[base+slot]->Health==(slot==active?0:10),"A native front miss must not redirect its larger hit or cancel independent backline rolls");++PoundCases;}
 if(run("block"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source);b.Pets[base+active]->States[BATTLEPET_STATE_Special_BlockedAttackCount]=1;auto hp=EnemyHP(b,source);PoundRoot(b,source);for(uint32 slot=0;slot<3;++slot)Require(hp[slot]-b.Pets[base+slot]->Health==(slot==active?0:10),"One real native finite block state cannot redirect Pound or suppress another recipient");Require(!b.Pets[base+active]->States[BATTLEPET_STATE_Special_BlockedAttackCount],"Pound must consume the intended front's one block state");++PoundCases;}
 if(run("immune"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source),blocked=(active+1)%3;b.Pets[base+blocked]->States[BATTLEPET_STATE_untargettable]=1;auto hp=EnemyHP(b,source);PoundRoot(b,source);for(uint32 slot=0;slot<3;++slot)Require(hp[slot]-b.Pets[base+slot]->Health==(slot==blocked?0:slot==active?20:10),"Native untargetability must remain independent for each fixed Pound recipient");++PoundCases;}
 if(run("round")||run("lethalround"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active)for(bool lethal:{false,true})if(run(lethal?"lethalround":"round")){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source);if(lethal)b.Pets[base+active]->Health=1;auto hp=EnemyHP(b,source);Require(b.CanCast(source/3,1587),"Actual native owned Pound admission failed");b.PrepareCast(source/3,1587);b.Teams[base/3]->Ready=true;b.Teams[base/3]->ActiveAbilityId=0;b.Teams[base/3]->activeAbilityTurn=b.Teams[base/3]->activeAbilityTurnMax=1;b.ProceedRound();for(uint32 slot=0;slot<3;++slot)Require(hp[slot]-b.Pets[base+slot]->Health==(slot==active?(lethal?1:20):10),"Actual selected native Pound through a complete round must honor active/backline and killing-hit paths");++PoundCases;}
 if(run("recast"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);uint32 base=EnemyBase(source),incoming=(active+1)%3;auto hp=EnemyHP(b,source);PoundRoot(b,source);b.SwapPet(base/3,base+incoming);Require(b.Teams[base/3]->ActivePetID==int32(base+incoming),"Real intervening opponent swap failed");PoundRoot(b,source);for(uint32 slot=0;slot<3;++slot)Require(hp[slot]-b.Pets[base+slot]->Health==((slot==active||slot==incoming)?30:20),"A later Pound must snapshot the newly selected front rather than reuse the preceding cast");++PoundCases;}
 if(run("bounds"))for(uint32 source:{0u,3u})for(uint32 active=0;active<3;++active){PetBattle b;PoundSetup(b,source,active);auto hp=EnemyHP(b,source);b.Teams[EnemyBase(source)/3]->TeamPetCount=99;PoundRoot(b,source);SplitDamage(b,source,active,hp);b.Teams[EnemyBase(source)/3]->TeamPetCount=3;++PoundCases;}
 if(run("missingsource"))for(uint32 source:{0u,3u}){PetBattle b;PoundSetup(b,source,1);auto hp=EnemyHP(b,source);auto saved=b.Pets[source];b.Pets[source].reset();Require(b.Cast(source,1587,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_NONE)==PETBATTLE_CAST_INTERNAL_ERROR&&hp==EnemyHP(b,source),"Missing native Pound caster must be rejected without effects");b.Pets[source]=saved;++PoundCases;}
 if(run("deadsource"))for(uint32 source:{0u,3u}){PetBattle b;PoundSetup(b,source,1);PetBattleAbilityTurn turn{};auto e=Hit(b,turn,EnemyBase(source),source);e.Kill(source);b.RoundResult=PETBATTLE_ROUND_RESULT_NONE;auto hp=EnemyHP(b,source);Require(!b.Pets[source]->IsAlive()&&b.Cast(source,1587,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_NONE)==PETBATTLE_CAST_INTERNAL_ERROR&&hp==EnemyHP(b,source),"A late trusted Pound cannot admit an actually dead caster");++PoundCases;}
 if(run("wrongteam"))for(uint32 source:{0u,3u}){PetBattle b;PoundSetup(b,source,1);uint32 base=EnemyBase(source);auto hp=EnemyHP(b,source);b.Pets[base]->TeamID=source/3;PoundRoot(b,source);Require(b.Pets[base]->Health==hp[0]&&hp[1]-b.Pets[base+1]->Health==20&&hp[2]-b.Pets[base+2]->Health==10,"Malformed foreign backline cannot receive or redirect hostile Pound damage");b.Pets[base]->TeamID=base/3;++PoundCases;}
 if(run("invalidteam"))for(uint32 source:{0u,3u}){PetBattle b;PoundSetup(b,source,1);auto hp=EnemyHP(b,source);b.Pets[source]->TeamID=2;Require(b.Cast(source,1587,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_NONE)==PETBATTLE_CAST_INTERNAL_ERROR&&hp==EnemyHP(b,source),"Invalid native caster team must be rejected before opponent lookup");b.Pets[source]->TeamID=source/3;++PoundCases;}
 if(run("other"))for(uint32 source:{0u,3u}){PetBattle b;PoundSetup(b,source,1);uint32 base=EnemyBase(source);auto hp=EnemyHP(b,source);b.Pets[source]->Abilities[0]=110;PetBattleAbilityTurn turn{};auto e=Bite(b,turn,source,base+1);auto amount=e.CalculateDamage(e.EffectInfo->Param[0]);Require(b.Cast(source,110,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_NONE)==PETBATTLE_CAST_OK&&hp[0]==b.Pets[base]->Health&&hp[1]-b.Pets[base+1]->Health==amount&&hp[2]==b.Pets[base+2]->Health,"Unrelated native single-target ability cannot inherit Pound targeting");++PoundCases;}
 if(run("owner"))for(uint32 source:{0u,3u}){PetBattle b;PoundSetup(b,source,1);auto hp=EnemyHP(b,source);Require(b.Cast(source,1587,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL,EnemyBase(source)+1)==PETBATTLE_CAST_INTERNAL_ERROR&&hp==EnemyHP(b,source),"A forged aura-owner context cannot authorize a Pound root");++PoundCases;}
 if(run("reflection")||run("reflectionmech"))for(uint32 source:{0u,3u})for(bool mechanical:{false,true})if(run(mechanical?"reflectionmech":"reflection")){PetBattle b;PoundSetup(b,source,0,OrdinarySpecies());if(mechanical)Racial(b,source,BATTLEPET_PETTYPE_MECHANICAL);for(auto p:b.Pets){p->States[BATTLEPET_STATE_Stat_CritChance]=0;p->States[BATTLEPET_STATE_Stat_Power]=0;}uint32 base=EnemyBase(source);Require(b.Cast(base,315,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL)==PETBATTLE_CAST_OK&&Aura(b,base,316),"Real native Spiked Skin producer failed");b.Pets[source]->Health=1;PetBattleAbilityTurn hitTurn{};auto firstHit=Hit(b,hitTurn,source,base);firstHit.EffectInfo=sBattlePetAbilityEffectStore.LookupEntry(3030);firstHit.AbilityID=1587;int32 expectedFirst=firstHit.CalculateDamage(firstHit.EffectInfo->Param[0]);Require(expectedFirst>0,"Native Spiked Skin mitigation calibration failed");auto hp=EnemyHP(b,source);PoundRoot(b,source);Require(hp[0]-b.Pets[base]->Health==expectedFirst,"Native reflected attack must retain its first actual opponent hit and real Spiked Skin mitigation");if(mechanical){Require(b.Pets[source]->IsAlive()&&!b.Pets[source]->States[BATTLEPET_STATE_Passive_Mechanical]&&hp[1]-b.Pets[base+1]->Health==10&&hp[2]-b.Pets[base+2]->Health==10,"Actual Mechanical caster revival must retain native Pound continuation");}else Require(!b.Pets[source]->IsAlive()&&hp[1]==b.Pets[base+1]->Health&&hp[2]==b.Pets[base+2]->Health&&b.PetXDied.size()==1&&b.PetXDied[0]==source,"A caster finally killed by real Spiked Skin must stop before Pound backline rows");++PoundCases;}
}
